// Room: Entry hall (interior designer). Inner air box [10,5,11,14,8,22]: x10..14, y5..8, z11..22.
// Entered through the entry door (11..12,5..7,10); doorways (9,5..6,12) parlour, (9,5..6,19) dining, (11,5..6,23) kitchen.
// Design: a dark-oak hall with the long stair up the east party wall (focal, newel lamp at its foot), a runner carpet
// from the front door to the kitchen, a coat post and a hall table with a seat on the west side, and three hanging lanterns.
// The stair's top step (13..14,9,16) sits in the storey-2 well the shell leaves open (plan: y9 over z11..16).
import { B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

const STAIR_WOOD = "spruce";     // plan: main stair treads are spruce_stairs
const HALL_WOOD = "dark_oak";    // dark-oak hall: newel, table, seat, stringer fill

export function build(g) {
  // runner carpet: front door (z10) to the kitchen doorway (z23), clear of both doorway lines
  for (let z = 11; z <= 22; z++) for (const x of [11, 12]) g.set(x, 5, z, ...B.block("red_carpet"));

  // the long stair: treads at x13..14, z12..16, rising one block per step (y = 5 + (z - 12)), backs to the south
  for (let z = 12; z <= 16; z++) {
    const y = 5 + (z - 12);
    for (const x of [13, 14]) {
      g.set(x, y, z, ...B.stairs(STAIR_WOOD, "south", "bottom"));
      // stringer: solid under each tread down to the floor so the stair is supported
      for (let yy = 5; yy < y; yy++) g.set(x, yy, z, ...B.block(`${HALL_WOOD}_planks`));
    }
  }

  // focal newel at the stair foot (x14, z11): dark-oak post with a standing lantern on top
  g.set(14, 5, 11, ...B.fence(HALL_WOOD));
  g.set(14, 6, 11, ...B.fence(HALL_WOOD));
  g.set(14, 7, 11, ...B.lantern(false));

  // coat post beside the front door (x10, z12): fence post, two high
  g.set(10, 5, 12, ...B.fence(HALL_WOOD));
  g.set(10, 6, 12, ...B.fence(HALL_WOOD));

  // hall table and seat on the west side, clear of the dining doorway at z19 (x10, z19 stays open)
  g.set(10, 5, 21, ...B.fence(HALL_WOOD));
  g.set(10, 6, 21, ...B.slab(HALL_WOOD, "top"));
  g.set(10, 5, 20, ...B.stairs(HALL_WOOD, "west", "bottom"));

  // hanging lanterns from the storey-2 floor (y9 is solid over x10..12 and at z17..22 over the well)
  g.set(12, 8, 15, ...B.lantern(true));
  g.set(11, 8, 13, ...B.lantern(true));
  g.set(11, 8, 21, ...B.lantern(true));
  g.set(13, 8, 19, ...B.lantern(true));
}
----
// Room: Upstairs landing. Inner air x10..14, y10..12, z11..22 (floor slab y9, stand y10).
// The main stair arrives at (13..14,10,17) through the open slab over x13..14 z11..15: that hole is railed in dark oak.
// The upper stair (spruce, facing south = high back south, plan convention) climbs x13..14 z19..22 to the top floor.
// Furniture: a narrow red runner up x11, a console table with a lantern on the west wall (the focal piece), a hall seat
// against the west wall, and a chest and barrel for linen at the south-west corner. Lanterns hang from the ceiling.
// Every doorway approach stays clear: (10,10..11,12), (10,10..11,19), (11,10..11,11), (11,10..11,22).
import { B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

export function build(g) {
  // upper stair: stand y10 at z18 rising to y13 at z22 (plan: y = 10 + (z - 19))
  for (const z of [19, 20, 21, 22]) for (const x of [13, 14]) {
    g.set(x, 10 + (z - 19), z, ...B.stairs("spruce", "south", "bottom"));
  }

  // rail around the main stair hole: west edge x12 z11..15, north z11 and south z15 at x13..14
  for (const z of [11, 12, 13, 14, 15]) g.set(12, 10, z, ...B.fence("dark_oak"));
  for (const x of [13, 14]) {
    g.set(x, 10, 11, ...B.fence("dark_oak"));
    g.set(x, 10, 15, ...B.fence("dark_oak"));
  }

  // runner: red carpet up the middle of the room (x11), from the study door to the back-bedroom door
  for (let z = 11; z <= 22; z++) g.set(11, 10, z, "red_carpet");

  // console table on the west wall, z14..16: dark oak legs at the ends, a top-slab tabletop at y11, a lantern on it
  g.set(10, 10, 14, ...B.fence("dark_oak"));
  g.set(10, 10, 16, ...B.fence("dark_oak"));
  for (const z of [14, 15, 16]) g.set(10, 11, z, ...B.slab("dark_oak", "top"));
  g.set(10, 12, 15, ...B.lantern(false));

  // hall seat: a dark oak stair against the west wall at z18, facing the room (high back west)
  g.set(10, 10, 18, ...B.stairs("dark_oak", "west", "bottom"));

  // linen store at the south-west corner: a chest and a barrel, clear of the bathroom and back-bedroom approaches
  g.set(10, 10, 21, "chest", { facing: "east", type: "single", waterlogged: "false" });
  g.set(10, 10, 22, "barrel", { facing: "up", open: "false" });

  // light: lanterns hang from the ceiling slab over the path and the stair foot, clear of every doorway head
  g.set(11, 12, 14, ...B.lantern(true));
  g.set(12, 12, 18, ...B.lantern(true));
  g.set(11, 12, 21, ...B.lantern(true));
}
----
// Room: Front bedroom (interior designer). Inner air box [1,10,7,8,12,15]; doorway (9,10..11,12) from the landing.
// Layout: fireplace breast on the W wall (x1..2, z11..13) with a mantel; a double bed (two red beds, head E against the
// party partition x=9, feet W) with a barrel nightstand; a purple rug on the floor; a bookshelf stack on the N corner;
// a chest wardrobe along the S wall (x6..8, z15); a lectern and a stair-seat chair at the SW; hanging lanterns for light.
// Walk path: doorway (8,10,12) -> (7,10,11) -> (7,10,10) reaches the bed foot side; the bay opens along z7 x2..7 (kept clear).
import { B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

const BREAST = "bricks";
const MANTEL = B.slab("smooth_quartz", "bottom");
const BED = "red_bed";
const RUG = "purple_carpet";

export function build(g) {
  // fireplace on the W party wall: breast x1 z11..13 y10..12, firebox at (2,10,12), bricks around, mantel shelf y12
  for (const y of [10, 11, 12]) for (const z of [11, 12, 13]) g.set(1, y, z, BREAST);
  g.set(2, 10, 11, BREAST); g.set(2, 11, 11, BREAST);
  g.set(2, 10, 13, BREAST); g.set(2, 11, 13, BREAST); g.set(2, 11, 12, BREAST);
